import {ServerChannel} from "./ServerChannel.js";
import {ServerSession} from "./ServerSession.js";
import {HTTPTransport} from "./HTTPTransport.js";
import {Utils} from "./Utils.js";
import * as crypto from "node:crypto";

/**
 * The server-side message broker.
 *
 * Events emitted:
 * <ul>
 *   <li><code>sessionAdded</code>, when a remote session, after a successful handshake, is added to this object</li>
 *   <li><code>sessionRemoved</code>, when a remote session is removed from this object, either explicitly by
 *   disconnecting, or because of a timeout</li>
 *   <li><code>channelAdded</code>, when a ServerChannel is added to this object</li>
 *   <li><code>channelRemoved</code>, when a ServerChannel is removed from this object</li>
 *   <li><code>subscribed</code>, when a ServerSession has subscribed to a ServerChannel</li>
 *   <li><code>unsubscribed</code>, when a ServerSession has unsubscribed from a ServerChannel</li>
 * </ul>
 */
export class CometDServer {
    #options;
    #httpTransport;
    #extensions = [];
    #channels = {};
    #sessions = {};
    #listeners = {};
    #context = {};
    #sweeper = null;
    #policy = null;

    /**
     * Creates a new instance.
     *
     * @param {object.<string, *>} options the configuration options
     */
    constructor(options) {
        this.#options = Utils.mixin({
            logLevel: "info",
            sweepPeriod: 997
        }, options);

        this.#channels["/meta/handshake"] = new ServerChannel(this, "/meta/handshake");
        this.#channels["/meta/connect"] = new ServerChannel(this, "/meta/connect");
        this.#channels["/meta/subscribe"] = new ServerChannel(this, "/meta/subscribe");
        this.#channels["/meta/unsubscribe"] = new ServerChannel(this, "/meta/unsubscribe");
        this.#channels["/meta/disconnect"] = new ServerChannel(this, "/meta/disconnect");

        this.#httpTransport = new HTTPTransport(this);

        this.#sweep();
    }

    /**
     * @returns {object} the options for this CometD server.
     */
    get options() {
        return this.#options;
    }

    /**
     * The security policy object that is interrogated for authorization.
     * It may define zero or all of the following methods, and the
     * callback parameters must be completed either by an error at
     * the first parameter, or by a truthy value at the second parameter.
     * If a method is missing, it is implied that the authorization is granted.
     * <ul>
     *   <li><code>canHandshake(session, message, callback)</code></li>
     *   <li><code>canCreate(session, message, channelName, callback)</code></li>
     *   <li><code>canSubscribe(session, message, channel, callback)</code></li>
     *   <li><code>canPublish(session, message, channel, callback)</code></li>
     * </ul>
     */
    get policy() {
        return this.#policy;
    }

    set policy(policy) {
        this.#policy = policy;
    }

    /**
     * Adds a listener function for the given event.
     *
     * @param {string} event the event type
     * @param {function} fn the listener function
     */
    addListener(event, fn) {
        Utils.addListener(this.#listeners, event, fn);
    }

    /**
     * Removes a listener function for the given event.
     *
     * @param {string} event the event type
     * @param {function} fn the listener function
     */
    removeListener(event, fn) {
        return Utils.removeListener(this.#listeners, event, fn);
    }

    /**
     * @param {string} event the event type
     * @returns {function[]} the listeners for the given event
     */
    listeners(event) {
        return this.#listeners[event] || [];
    }

    /**
     * @callback serverIncomingFn
     * @param {CometDServer} cometd - the CometD server
     * @param {ServerSession} session - the session receiving the message
     * @param {object} message - the incoming message
     * @param {boolCallbackFn} callback - the callback to complete:
     * true to continue the processing, false to stop the processing
     */
    /**
     * @callback serverOutgoingFn
     * @param {CometDServer} cometd - the CometD server
     * @param {ServerSession} [sender] - the session that sends the message
     * @param {ServerSession} session - the session the message is sent to
     * @param {object} message - the outgoing message
     * @param {boolCallbackFn} callback - the callback to complete:
     * true to continue the processing, false to stop the processing
     */

    /**
     * @typedef {object} ServerExtension
     * @property {serverIncomingFn} [incoming]
     * @property {serverOutgoingFn} [outgoing]
     */
    /**
     * Adds the given extension to the list of extensions.
     *
     * @param {ServerExtension} extension the extension to add
     */
    addExtension(extension) {
        this.#extensions.push(extension);
    }

    /**
     * Removes the given extension from the list of extensions.
     *
     * @param {ServerExtension} extension the extension to remove
     * @return {boolean} whether the extension was removed
     */
    removeExtension(extension) {
        let index = this.#extensions.indexOf(extension);
        if (index >= 0) {
            this.#extensions.splice(index, 1);
            return true;
        }
        return false;
    }

    /**
     * @returns {ServerExtension[]} the list of extensions
     */
    get extensions() {
        return this.#extensions.slice();
    }

    /**
     * The function that handles HTTP request and response,
     * typically to be passed to Node's HTTP server.
     * <pre>
     * var http = require("http");
     * var cometd = require("cometd-nodejs-server");
     * var cometdServer = cometd.createCometDServer();
     * var httpServer = http.createServer(cometdServer.handle);
     * </pre>
     *
     * @param request the HTTP request
     * @param response the HTTP response
     */
    handle(request, response) {
        this.#httpTransport.handle(request, response);
    }

    /**
     * @param {string} name the channel name
     * @returns {?ServerChannel} a ServerChannel with the given name,
     * or nothing if there is no channel with the given name
     * @see #createServerChannel
     */
    getServerChannel(name) {
        return this.#channels[name];
    }

    /**
     * Returns a ServerChannel with the given name.
     * If the channel already exists, returns it;
     * otherwise the channel is created and cached.
     *
     * @param {string} name the channel name
     * @returns {ServerChannel} a ServerChannel with the given name
     * @see #getServerChannel
     */
    createServerChannel(name) {
        let channel = this.getServerChannel(name);
        if (!channel) {
            channel = new ServerChannel(this, name);
            this.#addServerChannel(channel);
        }
        return channel;
    }

    /**
     * @param {string} id the session id
     * @returns {ServerSession} a ServerSession with the given session id,
     * or nothing if there is no session with the given id
     */
    getServerSession(id) {
        return this.#sessions[id];
    }

    /**
     * Returns a map of contextual information related to the message processing.
     *
     * @returns {object}
     */
    get context() {
        return this.#context;
    }

    /**
     * Closes this CometD server, stopping its activities.
     */
    close() {
        clearTimeout(this.#sweeper);
    }


    // PRIVATE APIs.


    _setContext(context) {
        if (context) {
            this.#context = Utils.mixin(this.context, context);
        } else {
            this.#context = {};
        }
    }

    _process(session, message, callback) {
        const reply = {
            id: message.id,
            channel: message.channel
        };

        // Non-enumerable property "reply" to avoid serializing
        // the reply property of client-side published messages.
        Object.defineProperty(message, "reply", {
            value: reply
        });

        if (!session) {
            CometDServer.#unknown(reply);
            callback();
        } else {
            if (!message.channel) {
                CometDServer.#error(reply, "400::channel_missing");
                callback();
            } else {
                this.#extendIncoming(session, message, (failure, result) => {
                    if (failure) {
                        callback(failure);
                    } else if (result) {
                        if (session) {
                            session._extendIncoming(message, (failure, result) => {
                                if (failure) {
                                    callback(failure);
                                } else if (result) {
                                    this.#process1(session, message, callback);
                                } else {
                                    CometDServer.#error(reply, "404::message_deleted");
                                    callback();
                                }
                            });
                        } else {
                            this.#process1(session, message, callback);
                        }
                    } else {
                        CometDServer.#error(reply, "404::message_deleted");
                        callback();
                    }
                });
            }
        }
    }

    _publish(channel, session, message, incoming, callback) {
        this._log("cometd.server", "publishing to", channel.name, message);
        const broadcast = channel.broadcast;
        if (broadcast) {
            delete message.id;
            delete message.clientId;
        }
        this.#notifyListeners(channel, session, message, (failure, result) => {
            if (failure) {
                callback(failure);
            } else if (result) {
                this.#publish1(channel, session, message, incoming, callback);
            } else {
                callback(undefined, false);
            }
        });
    }

    #extendIncoming(session, message, callback) {
        Utils.asyncFoldLeft(this.#extensions, true, (result, extension, loop) => {
            if (result) {
                if (extension.incoming) {
                    try {
                        extension.incoming(this, session, message, (failure, ret) => {
                            loop(failure, ret !== false);
                        });
                    } catch (failure) {
                        this._log("cometd.server", "extension failure", failure, failure.stack);
                        loop(undefined, true);
                    }
                } else {
                    loop(undefined, true);
                }
            } else {
                loop(undefined, false);
            }
        }, callback);
    }

    _extendOutgoing(sender, session, message, callback) {
        Utils.asyncFoldLeft(this.extensions.reverse(), true, (result, extension, loop) => {
            if (result) {
                if (extension.outgoing) {
                    try {
                        extension.outgoing(this, session, session, message, (failure, ret) => {
                            loop(failure, ret !== false);
                        });
                    } catch (failure) {
                        this._log("cometd.server", "extension failure", failure, failure.stack);
                        loop(undefined, true);
                    }
                } else {
                    loop(undefined, true);
                }
            } else {
                loop(undefined, false);
            }
        }, callback);
    }

    // TODO: move to HTTPTransport?
    _extendReply(session, reply, callback) {
        this._extendOutgoing(session, session, reply, (failure, result) => {
            if (failure) {
                callback(failure);
            } else if (result) {
                if (session) {
                    session._extendOutgoing(session, session, reply, callback);
                } else {
                    callback(undefined, reply);
                }
            } else {
                callback(undefined, null);
            }
        });
    }

    _newServerSession() {
        const id = crypto.randomBytes(20).toString("hex");
        return new ServerSession(this, id);
    }

    _removeServerSession(session, timeout) {
        const existing = this.#sessions[session.id];
        if (existing) {
            delete this.#sessions[session.id];
            Utils.notifyEvent(this.listeners("sessionRemoved"), [session, timeout]);
            session._removed(timeout);
        }
        return existing;
    }

    _removeServerChannel(channel) {
        const existing = this.#channels[channel.name];
        if (existing) {
            delete this.#channels[channel.name];
            Utils.notifyEvent(this.listeners("channelRemoved"), [channel]);
        }
        return existing;
    }

    _log(tag, args) {
        if (this.options.logLevel === "debug") {
            args = [].slice.call(arguments);
            args.splice(0, 1, new Date().toISOString() + ":" + tag + ": ");
            console.log.apply(console, args);
        }
    }


    #canHandshake(session, message, callback) {
        const p = this.policy;
        if (p && p.canHandshake) {
            p.canHandshake(session, message, (failure, result) => {
                callback(failure, result !== false);
            });
        } else {
            callback(undefined, true);
        }
    }

    #canCreate(session, message, channelName, callback) {
        const p = this.policy;
        if (p && p.canCreate) {
            p.canCreate(session, message, channelName, (failure, result) => {
                callback(failure, result !== false);
            });
        } else {
            callback(undefined, true);
        }
    }

    #canSubscribe(session, message, channel, callback) {
        const p = this.policy;
        if (p && p.canSubscribe) {
            p.canSubscribe(session, message, channel, (failure, result) => {
                callback(failure, result !== false);
            });
        } else {
            callback(undefined, true);
        }
    }

    #canPublish(channel, session, message, callback) {
        const p = this.policy;
        if (p && p.canPublish) {
            p.canPublish(session, message, channel, (failure, result) => {
                callback(failure, result !== false);
            });
        } else {
            callback(undefined, true);
        }
    }

    #addServerSession(session, message) {
        this.#sessions[session.id] = session;
        Utils.notifyEvent(this.listeners("sessionAdded"), [session, message]);
    }

    #addServerChannel(channel) {
        this.#channels[channel.name] = channel;
        Utils.notifyEvent(this.listeners("channelAdded"), [channel]);
    }

    #metaHandshake(session, message, callback) {
        this.#canHandshake(session, message, (failure, result) => {
            if (failure) {
                callback(failure);
            } else {
                const reply = message.reply;
                if (result) {
                    session._handshake();
                    this.#addServerSession(session, message);
                    reply.successful = true;
                    reply.clientId = session.id;
                    reply.version = "1.0";
                    reply.supportedConnectionTypes = ["long-polling"];
                } else {
                    CometDServer.#error(reply, "403::handshake_denied");
                    let advice = reply.advice;
                    if (!advice) {
                        advice = reply.advice = {};
                    }
                    if (!advice.reconnect) {
                        advice.reconnect = "none";
                    }
                }
                callback(undefined, result);
            }
        });
    }

    #metaConnect(session, message, callback) {
        const adviceIn = message.advice;
        if (adviceIn) {
            const timeout = adviceIn.timeout;
            session._setClientTimeout(timeout === undefined ? -1 : timeout);
            const interval = adviceIn.interval;
            session._setClientInterval(interval === undefined ? -1 : interval);
        } else {
            session._setClientTimeout(-1);
            session._setClientInterval(-1);
        }
        message.reply.successful = true;
        callback(undefined, true);
    }

    #metaSubscribe(session, message, callback) {
        const reply = message.reply;
        let subscriptions = message.subscription;
        reply.subscription = subscriptions;
        if (subscriptions) {
            if (!Array.isArray(subscriptions)) {
                subscriptions = [subscriptions];
            }
            Utils.asyncFoldLeft(subscriptions, true, (result, subscription, loop) => {
                if (result) {
                    let channel = this.getServerChannel(subscription);
                    if (!channel) {
                        this.#canCreate(session, message, subscription, (failure, result) => {
                            if (failure) {
                                loop(failure);
                            } else if (result) {
                                channel = this.createServerChannel(subscription);
                                this.#canSubscribe(session, message, channel, loop);
                            } else {
                                loop(undefined, false);
                            }
                        });
                    } else {
                        this.#canSubscribe(session, message, channel, loop);
                    }
                } else {
                    loop(undefined, false);
                }
            }, (failure, result) => {
                if (failure) {
                    callback(failure);
                } else if (result) {
                    Utils.asyncFoldLeft(subscriptions, true, (result1, subscription, loop) => {
                        if (result1) {
                            const channel = this.getServerChannel(subscription);
                            channel._subscribe(session, message, loop);
                        } else {
                            loop(undefined, false);
                        }
                    }, (failure2, result2) => {
                        if (failure2) {
                            callback(failure2);
                        } else {
                            if (result2) {
                                reply.successful = true;
                            } else {
                                CometDServer.#error(reply, "403::subscribe_failed");
                            }
                            callback(undefined, true);
                        }
                    });
                } else {
                    CometDServer.#error(reply, "403::subscribe_denied");
                    callback(undefined, true);
                }
            });
        } else {
            CometDServer.#error(reply, "403::subscription_missing");
            callback(undefined, true);
        }
    }

    #metaUnsubscribe(session, message, callback) {
        const reply = message.reply;
        let subscriptions = message.subscription;
        reply.subscription = subscriptions;
        if (subscriptions) {
            if (!Array.isArray(subscriptions)) {
                subscriptions = [subscriptions];
            }
            Utils.asyncFoldLeft(subscriptions, true, (result, subscription, loop) => {
                if (result) {
                    const channel = this.getServerChannel(subscription);
                    if (channel) {
                        channel._unsubscribe(session, message, loop);
                    } else {
                        loop(undefined, true);
                    }
                } else {
                    loop(undefined, false);
                }
            }, (failure, result) => {
                if (failure) {
                    callback(failure);
                } else {
                    if (result) {
                        reply.successful = true;
                    } else {
                        CometDServer.#error(reply, "403::unsubscribe_failed");
                    }
                    callback(undefined, true);
                }
            });
        } else {
            CometDServer.#error(reply, "403::subscription_missing");
            callback(undefined, true);
        }
    }

    #metaDisconnect(session, message, callback) {
        const reply = message.reply;
        reply.successful = true;
        this._removeServerSession(session, false);
        session._flush();
        callback(undefined, true);
    }

    #notifyListeners(channel, session, message, callback) {
        const channels = [];
        channel.wildNames.forEach(wildName => {
            const wild = this.getServerChannel(wildName);
            if (wild) {
                channels.push(wild);
            }
        });
        channels.push(channel);
        Utils.asyncFoldLeft(channels, true, (processChannel, ch, chLoop) => {
            if (processChannel) {
                const listeners = ch.listeners("message");
                this._log("cometd.server", "notifying", listeners.length, "listeners on", channel.name);
                Utils.asyncFoldLeft(listeners, true, (processListener, listener, lsLoop) => {
                    if (processListener) {
                        listener(session, ch, message, (failure, result) => {
                            lsLoop(failure, result !== false);
                        });
                    } else {
                        lsLoop(undefined, false);
                    }
                }, chLoop);
            } else {
                chLoop(undefined, false);
            }
        }, callback);
    }

    #notifySubscribers(channel, session, message) {
        const channels = [];
        channel.wildNames.forEach(wildName => {
            const wild = this.getServerChannel(wildName);
            if (wild) {
                channels.push(wild);
            }
        });
        channels.push(channel);

        // Avoid generating the JSON string for each subscriber.
        message = Utils.serialize(message);

        channels.forEach(channel => {
            const subscribers = channel.subscribers;
            this._log("cometd.server", "notifying", subscribers.length, "subscribers on", channel.name);
            subscribers.forEach(subscriber => {
                subscriber._deliver1(session, message, null);
            });
        });
    }

    #publish1(channel, session, message, incoming, callback) {
        if (channel.broadcast) {
            this._extendOutgoing(session, null, message, (failure, result) => {
                if (failure) {
                    callback(failure);
                } else if (result) {
                    this.#publish2(channel, session, message, callback);
                } else {
                    if (incoming) {
                        CometDServer.#error(message.reply, "404::message_deleted");
                    }
                    callback(undefined, false);
                }
            });
        } else {
            if (incoming) {
                this.#publish2(channel, session, message, callback);
            } else {
                callback(new Error("cannot publish to non-broadcast channel " + channel.name));
            }
        }
    }

    #publish2(channel, session, message, callback) {
        if (channel.meta) {
            switch (channel.name) {
                case "/meta/handshake":
                    this.#metaHandshake(session, message, callback);
                    break;
                case "/meta/connect":
                    this.#metaConnect(session, message, callback);
                    break;
                case "/meta/subscribe":
                    this.#metaSubscribe(session, message, callback);
                    break;
                case "/meta/unsubscribe":
                    this.#metaUnsubscribe(session, message, callback);
                    break;
                case "/meta/disconnect":
                    this.#metaDisconnect(session, message, callback);
                    break;
                default:
                    callback(new Error("invalid channel " + channel.id));
                    break;
            }
        } else {
            if (channel.broadcast) {
                this.#notifySubscribers(channel, session, message);
            }
            callback(undefined, true);
        }
    }

    #process1(session, message, callback) {
        const channelName = message.channel;
        session._cancelExpiration(channelName === "/meta/connect");
        let channel = this.getServerChannel(channelName);
        if (!channel) {
            this.#canCreate(session, message, channelName, (failure, result) => {
                if (failure) {
                    callback(failure);
                } else if (result) {
                    channel = this.createServerChannel(channelName);
                    this.#process2(channel, session, message, callback);
                } else {
                    CometDServer.#error(message.reply, "403::channel_denied");
                    callback();
                }
            });
        } else {
            this.#process2(channel, session, message, callback);
        }
    }

    #process2(channel, session, message, callback) {
        const reply = message.reply;
        if (channel.meta) {
            this._publish(channel, session, message, true, callback);
        } else {
            this.#canPublish(channel, session, message, (failure, result) => {
                if (failure) {
                    callback(failure);
                } else if (result) {
                    reply.successful = true;
                    this._publish(channel, session, message, true, callback);
                } else {
                    CometDServer.#error(reply, "403::publish_denied");
                    callback();
                }
            });
        }
    }

    #sweep() {
        for (let name in this.#channels) {
            if (this.#channels.hasOwnProperty(name)) {
                this.#channels[name]._sweep();
            }
        }
        for (let id in this.#sessions) {
            if (this.#sessions.hasOwnProperty(id)) {
                this.#sessions[id]._sweep();
            }
        }
        // TODO: need to sweep transports too?
        this.#sweeper = setTimeout(() => this.#sweep(), this.options.sweepPeriod);
    }

    static #error(reply, error) {
        reply.successful = false;
        reply.error = error;
    }

    static #unknown(reply) {
        this.#error(reply, "402::session_unknown");
        if (reply.channel === "/meta/handshake" || reply.channel === "/meta/connect") {
            let advice = reply.advice;
            if (!advice) {
                advice = reply.advice = {};
            }
            advice.reconnect = "handshake";
            advice.interval = 0;
        }
    }
}
